$readEnd=[DateTimeOffset]::Parse('2026-11-10T21:00:00+02:00')
if([DateTimeOffset]::UtcNow -ge $readEnd){throw 'Separate reconciliation read bound reached'}
$stateSha=(Get-FileHash -LiteralPath 'C:\ProgramData\AzureLocalBox\FoundationProfile-20261110-02\worker-moc-remove-LB-NODE02.state.json' -Algorithm SHA256).Hash.ToLowerInvariant()
$session=New-ComputeSession 'LB-NODE02'
