}catch{$result=@{status='read-only-source-events-failed';error=@{type=$_.Exception.GetType().FullName;category=$_.CategoryInfo.Category.ToString();line=[int]$_.InvocationInfo.ScriptLineNumber};originalRemoveOutcomeRemainsUnknown=$true;retryAllowed=$false;vmShutdownAllowed=$false}}
finally{if($session){Remove-PSSession $session -ErrorAction SilentlyContinue}}
